function MembershipPlansEditor() {
  const [plans, setPlans] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [savingId, setSavingId] = useState<number | null>(null);
  const [savedId, setSavedId] = useState<number | null>(null);
  const [creating, setCreating] = useState(false);
  const [newPlan, setNewPlan] = useState({
    tier: "basic",
    name: "",
    description: "",
    priceMonthly: 0,
    priceYearly: 0,
    durationDays: 30,
    dailyLikesLimit: 10,
    superLikesPerDay: 0,
    showAds: true,
    isActive: true,
    sortOrder: 0,
    color: "#6366f1",
    features: [] as string[],
  });

  useEffect(() => {
    fetch("/api/membership/plans", { credentials: "include" })
      .then((r) => r.json())
      .then((data) => {
        setPlans(Array.isArray(data) ? data : data.plans || []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const updatePlanField = (id: number, field: string, value: any) => {
    setPlans((prev) =>
      prev.map((p) => (p.id === id ? { ...p, [field]: value } : p))
    );
  };

  const toggleFeature = (id: number, feature: string) => {
    setPlans((prev) =>
      prev.map((p) => {
        if (p.id !== id) return p;
        const features = p.features || [];
        return {
          ...p,
          features: features.includes(feature)
            ? features.filter((f: string) => f !== feature)
            : [...features, feature],
        };
      })
    );
  };

  const handleSave = async (plan: any) => {
    setSavingId(plan.id);
    setSavedId(null);
    try {
      const { id, createdAt, updatedAt, ...body } = plan;
      const res = await fetch(`/api/admin/membership/plans/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(body),
      });
      if (!res.ok) throw new Error("Failed to save");
      setSavedId(plan.id);
      setTimeout(() => setSavedId(null), 2000);
    } catch (err) {
      console.error(err);
    } finally {
      setSavingId(null);
    }
  };

  const handleCreate = async () => {
    setCreating(true);
    try {
      const res = await fetch("/api/admin/membership/plans", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(newPlan),
      });
      if (!res.ok) throw new Error("Failed to create");
      const created = await res.json();
      setPlans((prev) => [...prev, created]);
      setNewPlan({
        tier: "basic",
        name: "",
        description: "",
        priceMonthly: 0,
        priceYearly: 0,
        durationDays: 30,
        dailyLikesLimit: 10,
        superLikesPerDay: 0,
        showAds: true,
        isActive: true,
        sortOrder: 0,
        color: "#6366f1",
        features: [],
      });
    } catch (err) {
      console.error(err);
    } finally {
      setCreating(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Delete this plan?")) return;
    try {
      await fetch(`/api/admin/membership/plans/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      setPlans((prev) => prev.filter((p) => p.id !== id));
