}

export interface AuthProfile {
  id: string;
  userId: string;
  name: string;
  age: number;
  gender: string;
  bio: string;
  city: string;
  location: string;
  interests: string[];
  photos: string[];
  isVisible: boolean;
  aiPersonaEnabled: boolean;
  aiTone: string;
  aiLanguage: string;
  aiProxyEnabled: boolean;
  aiChatPace: string;
  aiBoundaries: string[];
  intent: string | null;
  intentLockedAt: string | null;
  intentLockBroken: boolean;
  familyMode: boolean;
