const getRandom = <T,>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];
const getRandomSubset = <T,>(arr: T[], count: number): T[] => {
  const shuffled = [...arr].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count);
};

async function seed() {
  console.log("Seeding database with 170 profiles...");

  const existing = await db.select({ count: sql<number>`count(*)` }).from(profiles);
  if (Number(existing[0].count) > 0) {
    console.log(`Database already has ${existing[0].count} profiles. Skipping seed.`);
    return;
  }

  const createProfiles = async (
    names: string[],
    gender: "Male" | "Female" | "Trans" | "Couple",
    count: number,
    options?: { bioPool?: string[]; interestedIn?: string[] }
  ) => {
    for (let i = 0; i < count; i++) {
      const name = names[i % names.length];
      const isMumbaiPune = Math.random() < 0.5;
      const locationData = isMumbaiPune ? getRandom(mumbaiPuneLocations) : getRandom(otherLocations);

      const age = Math.floor(Math.random() * (35 - 21) + 21);
      const respectScore = Math.floor(Math.random() * (100 - 70) + 70);
      const bio = options?.bioPool ? getRandom(options.bioPool) : getRandom(bios);
      const interests = getRandomSubset(interestsList, 3 + Math.floor(Math.random() * 3));
      const photoPool = gender === "Male" ? malePhotos : gender === "Female" ? femalePhotos : gender === "Couple" ? couplePhotos : neutralPhotos;
      const photo = getRandom(photoPool);

      const intent = getRandom(intents);
      const familyMode = Math.random() < 0.25;
      const festivalPrefs = getRandomSubset(festivals, 2 + Math.floor(Math.random() * 3));

      const greenFlagStories = Object.entries(greenFlagAnswers).map(([prompt, answers]) => ({
        prompt,
        answer: Math.random() > 0.3 ? getRandom(answers) : "",
      })).filter(s => s.answer);

      let partner1Name = name;
      let partner2Name: string | undefined;
      let partner2Age: number | undefined;
      let partner2Gender: string | undefined;

      if (gender === "Couple" && name.includes(" & ")) {
        const parts = name.split(" & ");
        partner1Name = parts[0];
        partner2Name = parts[1];
        partner2Age = Math.floor(Math.random() * (35 - 21) + 21);
        const genderOptions = ["Male", "Female", "Trans"];
        partner2Gender = getRandom(genderOptions);
      }

      const hasAiProxy = Math.random() > 0.7;
      const membershipTier = hasAiProxy ? "gold" : getRandom(["basic", "basic", "silver", "gold"]);
      const membershipExpiresAt = membershipTier !== "basic" ? new Date(Date.now() + 365 * 24 * 60 * 60 * 1000) : undefined;

      const [user] = await db
        .insert(users)
        .values({
          phone: `+91${Math.floor(7000000000 + Math.random() * 3000000000)}`,
          isVerified: true,
          respectScore,
          membershipTier,
          ...(membershipExpiresAt && { membershipExpiresAt }),
        })
        .returning();

      await db.insert(profiles).values({
        userId: user.id,
        name: encrypt(partner1Name),
        age,
        gender,
        bio: encrypt(bio),
        city: locationData.city,
        location: locationData.loc,
        interests,
        photos: [photo],
        isVisible: true,
        aiPersonaEnabled: Math.random() > 0.5,
        aiTone: getRandom(["Friendly", "Witty", "Polite", "Flirty"]),
        aiLanguage: getRandom(["English", "Hindi", "Hinglish"]),
        aiProxyEnabled: hasAiProxy,
        aiChatPace: getRandom(["Slow", "Normal", "Fast"]),
        intent,
        intentLockedAt: new Date(),
        familyMode,
        festivalPrefs,
        hometownForFestivals: locationData.city,
        greenFlagStories,
        interestedIn: options?.interestedIn || undefined,
        dateReadiness: getRandom(["Chat-only", "Voice-ready", "Meet-ready"]),
        ...(partner2Name && {
          partner2Name: encrypt(partner2Name),
          partner2Age,
          partner2Gender,
        }),
      });
    }
  };

  await createProfiles(maleNames, "Male", 50);
  console.log("Created 50 male profiles");

  await createProfiles(femaleNames, "Female", 50);
  console.log("Created 50 female profiles");

  await createProfiles(transNames, "Trans", 20);
  console.log("Created 20 trans profiles");

  await createProfiles(coupleNames, "Couple", 50, {
    bioPool: coupleBios,
    interestedIn: ["Couple", "Female"],
  });
  console.log("Created 50 couple profiles");

  console.log("Seeding complete! 170 profiles created.");
}

seed()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error("Seed error:", err);
    process.exit(1);
  });

